{
  "nda-15": {
    "label": "NotMentioned",
    "justification": "The agreement only states that it does not grant implied intellectual property licenses, not that it grants no right at all to Confidential Information."
  },
  "nda-7": {
    "label": "Entailment",
    "justification": "Section 3(c) permits disclosure of Confidential Information to representatives, including contractors, advisors, and consultants, subject to need-to-know and protection requirements."
  },
  "nda-3": {
    "label": "Entailment",
    "justification": "The definition covers Confidential Information 'in any form,' which includes verbally conveyed information."
  },
  "nda-17": {
    "label": "NotMentioned",
    "justification": "The agreement does not address whether the Receiving Party may create copies of Confidential Information."
  },
  "nda-1": {
    "label": "Contradiction",
    "justification": "Confidential Information can also include information a reasonable person knows or should understand to be confidential, so it need not all be expressly identified."
  }
}

{
  "-nda-2": {
    "label": "Contradiction",
    "justification": "The agreement defines Confidential Information broadly as non-public information, know-how, and trade secrets, not as limited to technical information."
  },
  "-nda-19": {
    "label": "Entailment",
    "justification": "The agreement states that termination does not change rights and duties made while in effect and imposes post-termination confidentiality and non-solicitation periods."
  },
  "-nda-18": {
    "label": "Entailment",
    "justification": "The agreement prohibits soliciting or recruiting the other party's employees, contractors, or affiliated resources without consent, which are included among representatives."
  },
  "-nda-12": {
    "label": "Entailment",
    "justification": "The agreement expressly excludes independently developed information from Confidential Information."
  },
  "-nda-13": {
    "label": "Entailment",
    "justification": "The agreement excludes information lawfully received from another source without a confidentiality obligation from Confidential Information."
  },
  "-nda-16": {
    "label": "NotMentioned",
    "justification": "The agreement contains no provision requiring return or destruction of Confidential Information upon termination."
  },
  "-nda-20": {
    "label": "NotMentioned",
    "justification": "The agreement does not address retaining Confidential Information after any return or destruction."
  },
  "-nda-10": {
    "label": "NotMentioned",
    "justification": "The agreement does not prohibit disclosing the fact that the agreement was agreed or negotiated."
  },
  "-nda-11": {
    "label": "NotMentioned",
    "justification": "The agreement does not mention reverse engineering."
  },
  "-nda-4": {
    "label": "Entailment",
    "justification": "The agreement limits use and disclosure of Confidential Information to the purposes of the parties' business relationship."
  },
  "-nda-5": {
    "label": "Entailment",
    "justification": "The agreement permits disclosure to representatives, including employees, who need to know for the business relationship and are bound to protect the information."
  },
  "-nda-8": {
    "label": "Entailment",
    "justification": "The agreement requires seeking the highest protection and, when possible, giving prior notice before a legally required disclosure."
  }
}

